-- Tempo Set planning shared by the GFX grid script and GPhilDeck single re-renders.
-- Pure data: no REAPER calls. Moved unchanged from GPhil_tempoSet_render_gfx_direct.lua.
local M = {}

-- Actions generated by cfillion_Apply render preset (create action).lua
M.CMD_APPLY_GPHIL_CLICK = "_RSe07780b8d7eb28a48e88b3b7e3467d7c79cade66"
M.CMD_APPLY_GPHIL_RENDER = "_RS67c8ada3573313a7c135385939c19cbc2450964d"

-- Base pattern for CLICK renders (suffix will be replaced).
M.CLICK_PATTERN_BASE = "CLICKDATA/$project_$region_120"
-- Base pattern for regular renders (suffix will be replaced).
M.RENDER_PATTERN_BASE = "AUDIO/$region/$project_$region_160"

M.EXT_SECTION = "renderTempoSet"
M.PER_REGION_DEFAULT_STEP = 5
M.GROUP_KEY_SCALE = 1000000
M.PENDING_REGION_ROWS_KEY = "pending_region_rows_v1"
M.PENDING_QUEUE_OPTIONS_KEY = "pending_queue_options_v1"
M.SAVED_REGION_ROWS_KEY = "saved_region_rows_v1"
M.AUDIO_CHECK_OPTION_KEY = "pause_audio_check_v1"
M.MAX_ROW_ITERATIONS = 10000

M.RENDER_NUMERIC_KEYS = {
    "RENDER_SETTINGS",
    "RENDER_BOUNDSFLAG",
    "RENDER_CHANNELS",
    "RENDER_SRATE",
    "RENDER_STARTPOS",
    "RENDER_ENDPOS",
    "RENDER_TAILFLAG",
    "RENDER_TAILMS",
    "RENDER_ADDTOPROJ",
    "RENDER_DITHER",
    "RENDER_NORMALIZE",
    "RENDER_NORMALIZE_TARGET",
    "RENDER_BRICKWALL",
    "RENDER_FADEIN",
    "RENDER_FADEOUT",
    "RENDER_FADEINSHAPE",
    "RENDER_FADEOUTSHAPE",
    "RENDER_FADELPF",
    "RENDER_PADSTART",
    "RENDER_PADEND",
    "RENDER_TRIMSTART",
    "RENDER_TRIMEND",
    "RENDER_DELAY"
}

M.RENDER_STRING_KEYS = {
    "RENDER_FILE",
    "RENDER_PATTERN",
    "RENDER_EXTRAFILEDIR",
    "RENDER_FORMAT",
    "RENDER_FORMAT2"
}

function M.parse_bool(str, default_if_empty)
    if not str or str == "" then
        return default_if_empty
    end
    local s = str:lower()
    return (s == "y" or s == "yes" or s == "1" or s == "true")
end

function M.numeric_group_key(value)
    if not value then
        return "nil"
    end

    local scaled = value * M.GROUP_KEY_SCALE
    if scaled >= 0 then
        return tostring(math.floor(scaled + 0.5))
    end
    return tostring(math.ceil(scaled - 0.5))
end

function M.tempo_suffix_value(tempo)
    return tostring(math.floor((tempo or 0) + 0.5))
end

function M.row_is_enabled(row)
    return row == nil or row.enabled ~= false
end

function M.sanitize_name_for_storage(name)
    local text = name or ""
    text = text:gsub("[\t\r\n]", " ")
    return text
end

function M.serialize_region_rows(rows)
    local out = {}
    for i = 1, #rows do
        local row = rows[i]
        out[#out + 1] = table.concat({
            tostring(row.internal_index or -1),
            tostring(row.pos or 0),
            tostring(row.rgnend or 0),
            M.sanitize_name_for_storage(row.name),
            tostring(row.number or -1),
            tostring(row.base_tempo or 0),
            tostring(row.start_tempo or 0),
            tostring(row.step or 0),
            tostring(row.end_tempo or 0),
            row.render_click and "1" or "0",
            M.row_is_enabled(row) and "1" or "0"
        }, "\t")
    end
    return table.concat(out, "\n")
end

function M.deserialize_region_rows(blob)
    local rows = {}
    if not blob or blob == "" then
        return rows
    end

    for line in blob:gmatch("([^\n]+)") do
        local cols = {}
        for token in line:gmatch("([^\t]*)\t?") do
            if token == "" and #cols >= 10 then
                break
            end
            cols[#cols + 1] = token
        end

        if #cols >= 10 then
            rows[#rows + 1] = {
                internal_index = tonumber(cols[1]) or -1,
                pos = tonumber(cols[2]) or 0,
                rgnend = tonumber(cols[3]) or 0,
                name = cols[4] or "",
                number = tonumber(cols[5]) or -1,
                base_tempo = tonumber(cols[6]) or 0,
                start_tempo = tonumber(cols[7]) or 0,
                step = tonumber(cols[8]) or 0,
                end_tempo = tonumber(cols[9]) or 0,
                render_click = cols[10] == "1",
                enabled = cols[11] ~= "0"
            }
        end
    end

    return rows
end

function M.serialize_queue_options(options)
    options = options or {}
    return table.concat({
        "skip_existing=" .. (options.skip_existing and "1" or "0"),
        "mode=" .. (options.mode == "render_now" and "render_now" or "queue"),
        "pause_audio_check=" .. (options.pause_audio_check == false and "0" or "1")
    }, "\n")
end

function M.deserialize_queue_options(blob)
    local options = {
        skip_existing = false,
        mode = "queue",
        pause_audio_check = true
    }

    if not blob or blob == "" then
        return options
    end

    for line in blob:gmatch("([^\n]+)") do
        local key, value = line:match("^([^=]+)=(.*)$")
        if key == "skip_existing" then
            options.skip_existing = value == "1"
        elseif key == "pause_audio_check" then
            options.pause_audio_check = value ~= "0"
        elseif key == "mode" then
            options.mode = value == "render_now" and "render_now" or "queue"
        end
    end

    return options
end

-- Identity used by the grid's Save/Load to match saved rows to current regions.
function M.row_storage_key(row)
    return table.concat({
        tostring(row.number or -1),
        string.format("%.9f", row.pos or 0),
        string.format("%.9f", row.rgnend or 0),
        M.sanitize_name_for_storage(row.name):lower()
    }, "|")
end

function M.validate_row(row)
    if row.base_tempo <= 0 then
        return false, "Base tempo must be > 0"
    end
    if row.step == 0 then
        return false, "Step must be non-zero"
    end
    if (row.end_tempo - row.start_tempo) * row.step < 0 then
        return false, "Step direction must reach Max"
    end
    return true, nil
end

-- Counts the targets of the same loop build_per_region_queue_groups runs,
-- stopping one past `limit` (that function's guard truncates there).
function M.row_iteration_count(row, limit)
    limit = limit or M.MAX_ROW_ITERATIONS
    local tempo, count = row.start_tempo, 0
    while (row.step > 0 and tempo <= row.end_tempo) or (row.step < 0 and tempo >= row.end_tempo) do
        count = count + 1
        if count > limit then
            return count
        end
        tempo = tempo + row.step
    end
    return count
end

-- Replace last "_<number>" with tempo_str; if none, append.
function M.with_tempo_suffix(pattern, tempo_str)
    local prefix, existing = pattern:match("^(.*)_(%d+)%s*$")
    if prefix and existing then
        return prefix .. "_" .. tempo_str
    end
    return pattern .. "_" .. tempo_str
end

local function add_region_to_group(group, cfg, row_index)
    group.regions[#group.regions + 1] = cfg
    group.row_indexes[#group.row_indexes + 1] = row_index
end

-- Groups rows into click passes (same base) and music passes (same base and target).
function M.build_per_region_queue_groups(configs, tempo_multiplier)
    local click_groups = {}
    local click_by_key = {}
    local regular_groups = {}
    local regular_by_key = {}
    local numeric_group_key, tempo_suffix_value = M.numeric_group_key, M.tempo_suffix_value

    for row_index = 1, #configs do
        local cfg = configs[row_index]
        if M.row_is_enabled(cfg) and cfg and cfg.base_tempo and cfg.base_tempo > 0 and cfg.step and cfg.step ~= 0 then
            cfg.queue_row_index = row_index
            local base_actual = cfg.base_tempo * tempo_multiplier
            local base_suffix = tempo_suffix_value(cfg.base_tempo)

            if cfg.render_click then
                local click_key = table.concat({
                    numeric_group_key(base_actual),
                    base_suffix
                }, "|")
                local click_group = click_by_key[click_key]
                if not click_group then
                    click_group = {
                        base_tempo = cfg.base_tempo,
                        base_actual = base_actual,
                        base_suffix = base_suffix,
                        regions = {},
                        row_indexes = {}
                    }
                    click_by_key[click_key] = click_group
                    click_groups[#click_groups + 1] = click_group
                end
                add_region_to_group(click_group, cfg, row_index)
            end

            local tempo = cfg.start_tempo
            local guard = 0
            while (cfg.step > 0 and tempo <= cfg.end_tempo) or (cfg.step < 0 and tempo >= cfg.end_tempo) do
                local target_tempo = tempo
                local target_actual = target_tempo * tempo_multiplier
                local factor = target_actual / base_actual
                local tempo_display = tempo_suffix_value(target_tempo)
                local regular_key = table.concat({
                    numeric_group_key(base_actual),
                    numeric_group_key(target_actual),
                    tempo_display
                }, "|")
                local regular_group = regular_by_key[regular_key]
                if not regular_group then
                    regular_group = {
                        base_tempo = cfg.base_tempo,
                        base_actual = base_actual,
                        target_tempo = target_tempo,
                        target_actual = target_actual,
                        factor = factor,
                        tempo_display = tempo_display,
                        regions = {},
                        row_indexes = {}
                    }
                    regular_by_key[regular_key] = regular_group
                    regular_groups[#regular_groups + 1] = regular_group
                end
                add_region_to_group(regular_group, cfg, row_index)

                tempo = tempo + cfg.step
                guard = guard + 1
                if guard > M.MAX_ROW_ITERATIONS then
                    break
                end
            end
        end
    end

    return click_groups, regular_groups
end

return M
